export type MediaItemType =
  | "movie"
  | "series"
  | "season"
  | "episode"
  | "library"
  | "unknown";

export type Artwork = {
  primary?: string;
  backdrop?: string;
  logo?: string;
};

export type TrackSummary = {
  audioLanguages: string[];
  subtitleLanguages: string[];
};

export type MediaPerson = {
  name: string;
  role?: string;
  type?: string;
  imageUrl?: string;
};

export type MediaItem = {
  id: string;
  name: string;
  type: MediaItemType;
  jellyfinType?: string;
  overview?: string;
  year?: number;
  premiereDate?: string;
  runtimeTicks?: number;
  communityRating?: number;
  officialRating?: string;
  genres: string[];
  parentId?: string;
  seriesId?: string;
  seriesName?: string;
  seasonName?: string;
  indexNumber?: number;
  childCount?: number;
  locationType?: string;
  studios: string[];
  people: MediaPerson[];
  trackSummary: TrackSummary;
  userData: {
    played: boolean;
    favorite: boolean;
    playbackPositionTicks?: number;
    playedPercentage?: number;
    unplayedItemCount?: number;
  };
  artwork: Artwork;
};

export type Library = {
  id: string;
  name: string;
  collectionType?: string;
  itemCount?: number;
  artwork: Artwork;
};

export type PlaybackChapter = {
  name?: string;
  startPositionTicks?: number;
};

export type PlaybackSource = {
  id?: string;
  path?: string;
  container?: string;
  bitrate?: number;
  runtimeTicks?: number;
};

export type PlaybackMetadata = {
  itemId: string;
  sources: PlaybackSource[];
  chapters: PlaybackChapter[];
  trackSummary: TrackSummary;
};

import type { Api } from "@jellyfin/sdk";
import type { ImageType } from "@jellyfin/sdk/lib/generated-client";
import type { BaseItemDto } from "@jellyfin/sdk/lib/generated-client/models/base-item-dto";
import type { ImageRequestParameters } from "@jellyfin/sdk/lib/models/api/image-request-parameters";
import { ImageUrlsApi } from "@jellyfin/sdk/lib/utils/api/image-urls-api";
import type { Artwork, Library, MediaItem, MediaItemType, TrackSummary } from "./types";

const unique = (values: Array<string | null | undefined>) =>
  [...new Set(values.filter((value): value is string => Boolean(value)))];

const mapMediaItemType = (type?: string): MediaItemType => {
  switch (type) {
    case "Movie":
      return "movie";
    case "Series":
      return "series";
    case "Season":
      return "season";
    case "Episode":
      return "episode";
    case "CollectionFolder":
      return "library";
    default:
      return "unknown";
  }
};

export const getBestPrimaryImageUrl = (
  api: ImageUrlsApi,
  item: BaseItemDto,
  params: ImageRequestParameters = {},
): string => {
  const id = item.Id ?? "";

  if (item.ImageTags?.Primary) {
    return api.getItemImageUrlById(id, "Primary" as ImageType, {
      ...params,
      tag: item.ImageTags.Primary,
    });
  }

  if (item.SeriesPrimaryImageTag && item.SeriesId) {
    return api.getItemImageUrlById(item.SeriesId, "Primary" as ImageType, {
      ...params,
      tag: item.SeriesPrimaryImageTag,
    });
  }

  const record = item as Record<string, unknown>;
  if (record.PrimaryImageTag) {
    return api.getItemImageUrlById(id, "Primary" as ImageType, {
      ...params,
      tag: record.PrimaryImageTag as string,
    });
  }

  const parentPrimaryId = record.ParentPrimaryImageItemId as string | undefined;
  const parentPrimaryTag = record.ParentPrimaryImageTag as string | undefined;
  if (parentPrimaryTag && parentPrimaryId) {
    return api.getItemImageUrlById(parentPrimaryId, "Primary" as ImageType, {
      ...params,
      tag: parentPrimaryTag,
    });
  }

  if (item.AlbumPrimaryImageTag && item.AlbumId) {
    return api.getItemImageUrlById(item.AlbumId, "Primary" as ImageType, {
      ...params,
      tag: item.AlbumPrimaryImageTag,
    });
  }

  if (item.BackdropImageTags && item.BackdropImageTags.length > 0) {
    return api.getItemImageUrlById(id, "Backdrop" as ImageType, {
      ...params,
      tag: item.BackdropImageTags[0],
    });
  }

  if (item.SeriesThumbImageTag && item.SeriesId) {
    return api.getItemImageUrlById(item.SeriesId, "Thumb" as ImageType, {
      ...params,
      tag: item.SeriesThumbImageTag,
    });
  }

  if (item.ParentThumbImageTag && item.ParentThumbItemId) {
    return api.getItemImageUrlById(item.ParentThumbItemId, "Thumb" as ImageType, {
      ...params,
      tag: item.ParentThumbImageTag,
    });
  }

  if (
    item.ParentBackdropImageTags &&
    item.ParentBackdropImageTags.length > 0 &&
    item.ParentBackdropItemId
  ) {
    return api.getItemImageUrlById(item.ParentBackdropItemId, "Backdrop" as ImageType, {
      ...params,
      tag: item.ParentBackdropImageTags[0],
    });
  }

  return api.getItemImageUrlById(id);
};

export const getBestLogoImageUrl = (
  api: ImageUrlsApi,
  item: BaseItemDto,
  params: ImageRequestParameters = {},
): string | undefined => {
  const id = item.Id ?? "";

  if (item.ImageTags?.Logo) {
    return api.getItemImageUrlById(id, "Logo" as ImageType, {
      ...params,
      tag: item.ImageTags.Logo,
    });
  }

  if (item.ParentLogoImageTag && item.ParentLogoItemId) {
    return api.getItemImageUrlById(item.ParentLogoItemId, "Logo" as ImageType, {
      ...params,
      tag: item.ParentLogoImageTag,
    });
  }
};

export const mapArtwork = (
  jf: Api,
  item: BaseItemDto,
  params: ImageRequestParameters = {},
): Artwork => {
  const api = new ImageUrlsApi(jf.configuration);
  return {
    primary: getBestPrimaryImageUrl(api, item, params),
    backdrop: api.getItemBackdropImageUrls(item)[0],
    logo: getBestLogoImageUrl(api, item, params),
  };
};

export const mapTrackSummary = (item: BaseItemDto): TrackSummary => {
  const streams = item.MediaStreams ?? [];
  return {
    audioLanguages: unique(
      streams.filter((stream) => stream.Type === "Audio").map((stream) => stream.Language),
    ),
    subtitleLanguages: unique(
      streams.filter((stream) => stream.Type === "Subtitle").map((stream) => stream.Language),
    ),
  };
};

export const mapMediaItem = (item: BaseItemDto, jf?: Api): MediaItem => ({
  id: item.Id ?? "",
  name: item.Name ?? "",
  type: mapMediaItemType(item.Type),
  jellyfinType: item.Type,
  overview: item.Overview,
  year: item.ProductionYear,
  premiereDate: item.PremiereDate,
  runtimeTicks: item.RunTimeTicks,
  communityRating: item.CommunityRating,
  officialRating: item.OfficialRating,
  genres: item.Genres ?? [],
  parentId: item.ParentId,
  seriesId: item.SeriesId,
  seriesName: item.SeriesName,
  seasonName: item.SeasonName,
  indexNumber: item.IndexNumber,
  childCount: item.ChildCount,
  locationType: item.LocationType,
  studios: item.Studios?.map((studio) => studio.Name).filter((name): name is string => Boolean(name)) ?? [],
  people:
    item.People?.map((person) => ({
      name: person.Name ?? "",
      role: person.Role,
      type: person.Type,
      imageUrl: person.PrimaryImageTag && person.Id && jf
        ? new ImageUrlsApi(jf.configuration).getItemImageUrlById(person.Id, "Primary" as ImageType, {
            tag: person.PrimaryImageTag,
          })
        : undefined,
    })).filter((person) => Boolean(person.name)) ?? [],
  trackSummary: mapTrackSummary(item),
  userData: {
    played: item.UserData?.Played ?? false,
    favorite: item.UserData?.IsFavorite ?? false,
    playbackPositionTicks: item.UserData?.PlaybackPositionTicks,
    playedPercentage: item.UserData?.PlayedPercentage,
    unplayedItemCount: item.UserData?.UnplayedItemCount,
  },
  artwork: jf ? mapArtwork(jf, item) : {},
});

export const mapLibrary = (item: BaseItemDto, jf?: Api): Library => ({
  id: item.Id ?? "",
  name: item.Name ?? "",
  collectionType: item.CollectionType,
  itemCount: item.ChildCount,
  artwork: jf ? mapArtwork(jf, item) : {},
});

import type { Api } from "@jellyfin/sdk";
import type {
  ImageType,
  ItemFields,
  ItemsApiGetItemsRequest,
  ItemsApiGetResumeItemsRequest,
  MediaInfoApiGetPlaybackInfoRequest,
  TvShowsApiGetNextUpRequest,
  UserLibraryApiGetLatestMediaRequest,
} from "@jellyfin/sdk/lib/generated-client";
import type { BaseItemDto } from "@jellyfin/sdk/lib/generated-client/models/base-item-dto";
import type { ImageRequestParameters } from "@jellyfin/sdk/lib/models/api/image-request-parameters";
import { ImageUrlsApi } from "@jellyfin/sdk/lib/utils/api/image-urls-api";
import { Effect } from "effect";
import { isArray, isEmptyArray } from "effect/Array";
import { HttpError, MutationError, NoEpisodeFound } from "../../error";
import { AuthService, AuthServiceLayer } from "../auth";
import {
  getBestLogoImageUrl as getCatalogueLogoImageUrl,
  getBestPrimaryImageUrl as getCataloguePrimaryImageUrl,
} from "./catalogue";

/*
 *
 *
 *
 *  Helpers
 *
 *
 *
 */

function arrayToObjectWithDuplicates<K extends PropertyKey, V>(
  entries: readonly (readonly [K, V])[]
): Record<K, V | V[]> {
  return entries.reduce(
    (acc, [key, value]) => {
      const existing = acc[key];

      if (existing !== undefined) {
        acc[key] = Array.isArray(existing)
          ? [...existing, value]
          : [existing, value];
      } else {
        acc[key] = value;
      }

      return acc;
    },
    {} as Record<K, V | V[]>
  );
}

const getImageByKey = (jf: Api, item: BaseItemDto, keyTag: ImageType) =>
  new ImageUrlsApi(jf.configuration).getItemImageUrl(item, keyTag, {
    quality: 75,
  });

/**
 * Jellyfin-Web–style fallback chain for the best available primary image.
 * Tries, in order:
 *  1. ImageTags.Primary  (own item)
 *  2. SeriesPrimaryImageTag + SeriesId
 *  3. PrimaryImageTag    (some DTOs carry this at top-level with own Id)
 *  4. ParentPrimaryImageTag + ParentPrimaryImageItemId (inferred from ParentId)
 *  5. AlbumPrimaryImageTag + AlbumId
 *  6. BackdropImageTags  (first own backdrop)
 *  7. SeriesThumbImageTag + SeriesId
 *  8. ParentThumbImageTag + ParentThumbItemId
 *  9. ParentBackdropImageTags + ParentBackdropItemId (first parent backdrop)
 * Falls back to the tagless `/Items/{id}/Images/Primary` URL.
 */
const getBestPrimaryImageUrl = (
  api: ImageUrlsApi,
  item: BaseItemDto,
  params: ImageRequestParameters = {},
): string => {
  const id = item.Id ?? "";

  // 1. Own primary tag
  if (item.ImageTags?.Primary) {
    return api.getItemImageUrlById(id, "Primary" as ImageType, {
      ...params,
      tag: item.ImageTags.Primary,
    });
  }

  // 2. Series primary
  if (item.SeriesPrimaryImageTag && item.SeriesId) {
    return api.getItemImageUrlById(item.SeriesId, "Primary" as ImageType, {
      ...params,
      tag: item.SeriesPrimaryImageTag,
    });
  }

  // 3. Top-level PrimaryImageTag (rare but present on some DTOs)
  if ((item as Record<string, unknown>).PrimaryImageTag) {
    return api.getItemImageUrlById(id, "Primary" as ImageType, {
      ...params,
      tag: (item as Record<string, unknown>).PrimaryImageTag as string,
    });
  }

  // 4. Parent primary
  const parentPrimaryId =
    (item as Record<string, unknown>).ParentPrimaryImageItemId as
      | string
      | undefined;
  const parentPrimaryTag =
    (item as Record<string, unknown>).ParentPrimaryImageTag as
      | string
      | undefined;
  if (parentPrimaryTag && parentPrimaryId) {
    return api.getItemImageUrlById(parentPrimaryId, "Primary" as ImageType, {
      ...params,
      tag: parentPrimaryTag,
    });
  }

  // 5. Album primary (music items)
  if (item.AlbumPrimaryImageTag && item.AlbumId) {
    return api.getItemImageUrlById(item.AlbumId, "Primary" as ImageType, {
      ...params,
      tag: item.AlbumPrimaryImageTag,
    });
  }

  // 6. Own backdrop (first)
  if (item.BackdropImageTags && item.BackdropImageTags.length > 0) {
    return api.getItemImageUrlById(id, "Backdrop" as ImageType, {
      ...params,
      tag: item.BackdropImageTags[0],
    });
  }

  // 7. Series thumb
  if (item.SeriesThumbImageTag && item.SeriesId) {
    return api.getItemImageUrlById(item.SeriesId, "Thumb" as ImageType, {
      ...params,
      tag: item.SeriesThumbImageTag,
    });
  }

  // 8. Parent thumb
  if (item.ParentThumbImageTag && item.ParentThumbItemId) {
    return api.getItemImageUrlById(
      item.ParentThumbItemId,
      "Thumb" as ImageType,
      { ...params, tag: item.ParentThumbImageTag },
    );
  }

  // 9. Parent backdrop (first)
  if (
    item.ParentBackdropImageTags &&
    item.ParentBackdropImageTags.length > 0 &&
    item.ParentBackdropItemId
  ) {
    return api.getItemImageUrlById(
      item.ParentBackdropItemId,
      "Backdrop" as ImageType,
      { ...params, tag: item.ParentBackdropImageTags[0] },
    );
  }

  // 10. Tagless fallback
  return api.getItemImageUrlById(id);
};

/**
 * Fallback chain for the best available Logo image URL.
 *  1. ImageTags.Logo (own item)
 *  2. ParentLogoImageTag + ParentLogoItemId
 * Returns undefined when no logo metadata is available.
 */
const getBestLogoImageUrl = (
  api: ImageUrlsApi,
  item: BaseItemDto,
  params: ImageRequestParameters = {},
): string | undefined => {
  const id = item.Id ?? "";

  // 1. Own logo tag
  if (item.ImageTags?.Logo) {
    return api.getItemImageUrlById(id, "Logo" as ImageType, {
      ...params,
      tag: item.ImageTags.Logo,
    });
  }

  // 2. Parent logo
  if (item.ParentLogoImageTag && item.ParentLogoItemId) {
    return api.getItemImageUrlById(item.ParentLogoItemId, "Logo" as ImageType, {
      ...params,
      tag: item.ParentLogoImageTag,
    });
  }

  return;
};

const getImagesFromTags = (
  tags: BaseItemDto["ImageTags"],
  jf: Api,
  item: BaseItemDto
) => {
  if (!tags) {
    return {};
  }
  const images = Object.entries(tags).map(
    ([k, _v]) => [k, getImageByKey(jf, item, k as ImageType)] as const
  );

  return arrayToObjectWithDuplicates(images);
};

export type WithImage<T> = T extends Array<infer U>
  ? Array<U & { Image: string; Images: ReturnType<typeof getImagesFromTags> }>
  : T extends undefined
    ? undefined
    : T & { Image: string; Images: ReturnType<typeof getImagesFromTags> };

export const getImages =
  (jf: Api) =>
  <T extends BaseItemDto | BaseItemDto[] | undefined>(
    items: T
  ): Effect.Effect<WithImage<T>, never, never> => {
    if (!items) {
      return Effect.succeed(undefined as WithImage<T>);
    }

    return Effect.sync(() => {
      if (isArray(items)) {
        return items.map((item) => {
          const imageTags = getImagesFromTags(
            item.ImageTags,
            // jf.basePath,
            jf,
            // item.Id as string
            item
          );

          return {
            ...item,
            Image: getCataloguePrimaryImageUrl(
              new ImageUrlsApi(jf.configuration),
              item,
            ),
            Images: Object.assign(imageTags, {
              Backdrop: new ImageUrlsApi(
                jf.configuration
              ).getItemBackdropImageUrls(item),
              ...(!imageTags.Logo && {
                Logo: getCatalogueLogoImageUrl(
                  new ImageUrlsApi(jf.configuration),
                  item,
                ),
              }),
            }),
          };
        }) as unknown as WithImage<T>;
      }

      const imageTags = getImagesFromTags(
        items.ImageTags,
        jf,
        // jf.basePath,
        // items.Id as string
        items
      );

      return {
        ...items,
        Image: getCataloguePrimaryImageUrl(
          new ImageUrlsApi(jf.configuration),
          items,
          { quality: 40 },
        ),
        Images: Object.assign(imageTags, {
          Backdrop: new ImageUrlsApi(jf.configuration).getItemBackdropImageUrls(
            items
          ),
          ...(!imageTags.Logo && {
            Logo: getCatalogueLogoImageUrl(
              new ImageUrlsApi(jf.configuration),
              items,
            ),
          }),
        }),
      } as unknown as WithImage<T>;
    });
  };

const SUPPORTED_COLLECTION_TYPES = ["movies", "tvshows"] as const;

// Helper function to filter supported libraries
const filterSupportedLibraries = (items?: BaseItemDto[]) =>
  Effect.succeed(
    items?.filter(
      (item) =>
        item.CollectionType &&
        // biome-ignore lint/suspicious/noExplicitAny: filtering
        SUPPORTED_COLLECTION_TYPES.includes(item.CollectionType as any)
    ) ?? []
  );

/*
 *
 *
 *
 *  Jellyfin Service
 *
 *
 *
 */

export class JellyfinService extends Effect.Service<JellyfinService>()(
  "JellyfinService",
  {
    dependencies: [AuthServiceLayer],
    effect: Effect.gen(function* () {
      const auth = yield* AuthService;

      /*
       *
       *
       *  Libraries Methods
       *
       *
       */

      // Helper function to fetch user views from the API
      const fetchUserViews = (jf: Api) =>
        Effect.tryPromise({
          try: async () => {
            const { getUserViewsApi } = await import(
              "@jellyfin/sdk/lib/utils/api/user-views-api"
            );
            return await getUserViewsApi(jf).getUserViews();
          },
          catch: (e) => new HttpError({ status: 0, message: String(e) }),
        });

      const getLibraries = () =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();

          // Step 1: Fetch user views from API
          const response = yield* fetchUserViews(jf).pipe(
            Effect.flatMap((data) =>
              data.status !== 200
                ? Effect.fail(
                    new HttpError({
                      status: data.status,
                      message: data.statusText,
                    })
                  )
                : Effect.succeed(data)
            )
          );

          // Step 2: Validate the HTTP response
          // const validResponse = yield* validateResponse(response);

          // Step 3: Filter libraries to only include supported collection types
          const filteredLibraries = yield* filterSupportedLibraries(
            response.data?.Items
          );

          // Step 4: Add image URLs to each library
          const librariesWithImages = yield* getImages(jf)(filteredLibraries);

          return librariesWithImages;
        });

      /*
       *
       *
       *  Items Helpers
       *
       *
       */
      const fetchItems = (jf: Api, params: ItemsApiGetItemsRequest) =>
        Effect.tryPromise({
          try: async () => {
            const { getItemsApi } = await import(
              "@jellyfin/sdk/lib/utils/api/items-api"
            );
            return await getItemsApi(jf).getItems(params);
          },
          catch: (e) => new HttpError({ status: 0, message: String(e) }),
        });

      const fetchResumeItems = (
        jf: Api,
        params: ItemsApiGetResumeItemsRequest
      ) =>
        Effect.tryPromise({
          try: async () => {
            const { getItemsApi } = await import(
              "@jellyfin/sdk/lib/utils/api/items-api"
            );
            return await getItemsApi(jf).getResumeItems(params);
          },
          catch: (e) => new HttpError({ status: 0, message: String(e) }),
        });

      const fetchNextupItems = (jf: Api, params: TvShowsApiGetNextUpRequest) =>
        Effect.tryPromise({
          try: async () => {
            const { getTvShowsApi } = await import(
              "@jellyfin/sdk/lib/utils/api/tv-shows-api"
            );
            return await getTvShowsApi(jf).getNextUp(params);
          },
          catch: (e) => new HttpError({ status: 0, message: String(e) }),
        });

      const fetchLatestItems = (
        jf: Api,
        params: UserLibraryApiGetLatestMediaRequest
      ) =>
        Effect.tryPromise({
          try: async () => {
            const { getUserLibraryApi } = await import(
              "@jellyfin/sdk/lib/utils/api/user-library-api"
            );
            return await getUserLibraryApi(jf).getLatestMedia(params);
          },
          catch: (e) => new HttpError({ status: 0, message: String(e) }),
        });

      const fetchPlaybackState = (
        jf: Api,
        params: MediaInfoApiGetPlaybackInfoRequest
      ) =>
        Effect.tryPromise({
          try: async () => {
            const { getMediaInfoApi } = await import(
              "@jellyfin/sdk/lib/utils/api/media-info-api"
            );
            return await getMediaInfoApi(jf).getPlaybackInfo(params);
          },
          catch: (e) => new HttpError({ status: 0, message: String(e) }),
        });
      /*
       *
       *
       *  Items Methods
       *
       *
       */
      const getItem = (id: string, params?: ItemsApiGetItemsRequest) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();

          const res = yield* fetchItems(jf, {
            userId: user.Id,
            ids: [id],
            enableImages: true,
            enableUserData: true,
            ...params,
            fields: [
              "ParentId",
              "ChildCount",
              "Path",
              "MediaStreams",
              "Chapters",
              "MediaSources",
              ...(params?.fields ? [...params.fields] : []),
            ],
          }).pipe(
            Effect.flatMap((data) =>
              data.status !== 200
                ? Effect.fail(
                    new HttpError({
                      status: data.status,
                      message: data.statusText,
                    })
                  )
                : Effect.succeed(data)
            )
          );

          if (
            (res.data.Items && isEmptyArray(res.data.Items)) ||
            res.data.Items === undefined
          ) {
            return yield* Effect.fail(
              new HttpError({
                status: 404,
                message: "no item found",
              })
            );
          }

          const item = res.data.Items[0];

          return yield* getImages(jf)(item);
        });

      const getItems = (params?: ItemsApiGetItemsRequest) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();

          const res = yield* fetchItems(jf, {
            userId: user.Id,
            ...params,
          }).pipe(
            Effect.flatMap((data) =>
              data.status !== 200
                ? Effect.fail(
                    new HttpError({
                      status: data.status,
                      message: data.statusText,
                    })
                  )
                : Effect.succeed(data)
            )
          );

          if (
            (res.data.Items && isEmptyArray(res.data.Items)) ||
            res.data.Items === undefined
          ) {
            return yield* Effect.fail(
              new HttpError({
                status: 404,
                message: "no item found",
              })
            );
          }

          const items = res.data.Items;

          return yield* getImages(jf)(items);
        });

      const getResumeItems = (params?: ItemsApiGetResumeItemsRequest) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();

          const res = yield* fetchResumeItems(jf, {
            userId: user.Id,
            enableUserData: true,
            limit: 6,
            ...params,
            fields: ["ParentId", "MediaSources", "MediaStreams"].concat(
              params?.fields ?? []
            ) as ItemFields[],
          }).pipe(
            Effect.flatMap((data) =>
              data.status !== 200
                ? Effect.fail(
                    new HttpError({
                      status: data.status,
                      message: data.statusText,
                    })
                  )
                : Effect.succeed(data)
            )
          );

          if (
            (res.data.Items && isEmptyArray(res.data.Items)) ||
            res.data.Items === undefined
          ) {
            return yield* Effect.fail(
              new HttpError({
                status: 404,
                message: "no item found",
              })
            );
          }

          const items = res.data.Items;

          return yield* getImages(jf)(items);
        });

      const getNextupItems = (params?: ItemsApiGetResumeItemsRequest) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();

          const res = yield* fetchNextupItems(jf, {
            userId: user.Id,
            enableUserData: true,
            limit: 6,
            ...params,
            fields: ["ParentId", "MediaSources", "MediaStreams"].concat(
              params?.fields ?? []
            ) as ItemFields[],
          }).pipe(
            Effect.flatMap((data) =>
              data.status !== 200
                ? Effect.fail(
                    new HttpError({
                      status: data.status,
                      message: data.statusText,
                    })
                  )
                : Effect.succeed(data)
            )
          );

          if (
            (res.data.Items && isEmptyArray(res.data.Items)) ||
            res.data.Items === undefined
          ) {
            return yield* Effect.fail(
              new HttpError({
                status: 404,
                message: "no item found",
              })
            );
          }

          const items = res.data.Items;

          return yield* getImages(jf)(items);
        });

      const getLatestMedia = (params?: UserLibraryApiGetLatestMediaRequest) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();

          const res = yield* fetchLatestItems(jf, {
            userId: user.Id,
            enableUserData: true,
            limit: 6,
            ...params,
            fields: ["ParentId"].concat(params?.fields ?? []) as ItemFields[],
          }).pipe(
            Effect.flatMap((data) =>
              data.status !== 200
                ? Effect.fail(
                    new HttpError({
                      status: data.status,
                      message: data.statusText,
                    })
                  )
                : Effect.succeed(data)
            )
          );

          if ((res.data && isEmptyArray(res.data)) || res.data === undefined) {
            return yield* Effect.fail(
              new HttpError({
                status: 404,
                message: "no item found",
              })
            );
          }

          const items = res.data;

          return yield* getImages(jf)(items);
        });

      const getNextEpisode = (item: BaseItemDto) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();

          if (!item.IndexNumber) {
            return yield* new NoEpisodeFound();
          }

          // Current Episode Details
          const seasonId = item.ParentId ?? undefined;
          const currentIndex = item.IndexNumber;

          // Fetch all episodes in this season; we cannot rely on
          // `startIndex` to filter by IndexNumber — it is a pagination
          // offset, so e.g. on episode 1 (currentIndex+1=2) the API
          // returns the third episode in the result set, skipping the
          // actual next one. Likewise, we cannot trust the returned
          // sort order, so we pick the candidate with the smallest
          // IndexNumber strictly greater than the current episode.
          const res = yield* getItems({
            userId: user.Id,
            parentId: seasonId,
            fields: ["ParentId", "MediaStreams", "ParentId"],
            enableUserData: true,
            includeItemTypes: ["Episode"],
            sortBy: ["IndexNumber"],
            sortOrder: ["Ascending"],
            enableImages: true,
          });

          const next = res.reduce<(typeof res)[number] | undefined>(
            (best, candidate) => {
              if (typeof candidate.IndexNumber !== "number") {
                return best;
              }
              if (candidate.IndexNumber <= currentIndex) {
                return best;
              }
              if (
                !best ||
                typeof best.IndexNumber !== "number" ||
                candidate.IndexNumber < best.IndexNumber
              ) {
                return candidate;
              }
              return best;
            },
            undefined
          );

          if (!next) {
            return yield* new NoEpisodeFound();
          }

          return yield* getImages(jf)(next);
        });

      const getPlaybackState = (
        id: string,
        params?: MediaInfoApiGetPlaybackInfoRequest
      ) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();

          const res = yield* fetchPlaybackState(jf, {
            userId: user.Id,
            itemId: id,
            ...params,
          }).pipe(
            Effect.flatMap((data) =>
              data.status !== 200
                ? Effect.fail(
                    new HttpError({
                      status: data.status,
                      message: data.statusText,
                    })
                  )
                : Effect.succeed(data)
            )
          );

          if (!res.data) {
            return yield* Effect.fail(
              new HttpError({
                status: 404,
                message: "no item found",
              })
            );
          }
          return res.data;
        });
      /*
       *
       *
       *
       *
       *
       * Mutations
       *
       *
       *
       *
       *
       */
      const markItemPlayed = (id: string) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();
          yield* Effect.tryPromise({
            try: async (signal) => {
              const { getPlaystateApi } = await import(
                "@jellyfin/sdk/lib/utils/api/playstate-api"
              );
              await getPlaystateApi(jf).markPlayedItem(
                {
                  userId: user.Id,
                  itemId: id,
                },
                { signal }
              );
            },
            catch: (e) =>
              new MutationError({
                mutation: "MarkPlayedItem",
                message: (e as Error).message,
              }),
          });
        });

      const markItemUnPlayed = (id: string) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();
          yield* Effect.tryPromise({
            try: async (signal) => {
              const { getPlaystateApi } = await import(
                "@jellyfin/sdk/lib/utils/api/playstate-api"
              );
              await getPlaystateApi(jf).markUnplayedItem(
                {
                  userId: user.Id,
                  itemId: id,
                },
                { signal }
              );
            },
            catch: (e) =>
              new MutationError({
                mutation: "MarkUnPlayedItem",
                message: (e as Error).message,
              }),
          });
        });

      const markItemFavorite = (id: string) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();
          yield* Effect.tryPromise({
            try: async (signal) => {
              const { getUserLibraryApi } = await import(
                "@jellyfin/sdk/lib/utils/api/user-library-api"
              );
              await getUserLibraryApi(jf).markFavoriteItem(
                {
                  userId: user.Id,
                  itemId: id,
                },
                { signal }
              );
            },
            catch: (e) =>
              new MutationError({
                mutation: "MarkItemFavorite",
                message: (e as Error).message,
              }),
          });
        });

      const markItemUnFavorite = (id: string) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();
          yield* Effect.tryPromise({
            try: async (signal) => {
              const { getUserLibraryApi } = await import(
                "@jellyfin/sdk/lib/utils/api/user-library-api"
              );
              await getUserLibraryApi(jf).unmarkFavoriteItem(
                {
                  userId: user.Id,
                  itemId: id,
                },
                { signal }
              );
            },
            catch: (e) =>
              new MutationError({
                mutation: "MarkItemUnFavorite",
                message: (e as Error).message,
              }),
          });
        });

      return {
        getLibraries,
        getItem,
        getItems,
        getResumeItems,
        getNextupItems,
        getLatestMedia,
        getNextEpisode,
        getPlaybackState,

        /*
         *
         * Mutations
         *
         */

        markItemPlayed,
        markItemUnPlayed,
        markItemFavorite,
        markItemUnFavorite,
      };
    }),
  }
) {}

export const JellyfinServiceLayer = JellyfinService.Default;

import type { Api, RecommendedServerInfo } from "@jellyfin/sdk";
import type { UserDto } from "@jellyfin/sdk/lib/generated-client";
import { appDataDir } from "@tauri-apps/api/path";
import { Stronghold } from "@tauri-apps/plugin-stronghold";
import { Effect, Ref } from "effect";
import { commands } from "~/lib/tauri";
import {
  AuthError,
  NoPasswordFound,
  NoServerFound,
  NoTokenFound,
  NoUserFound,
} from "../../error";
import {
  JellyfinClientService,
  JellyfinClientServiceLayer,
} from "../jellyfin/client";
import { AuthStorageService, AuthStorageServiceLayer } from "../storage/auth";

/*
 *
 *
 *
 * Stronghold Helpers
 *
 *
 *
 */

function createKey(serverAddress: string, username: string): string {
  return `${serverAddress}:${username}`;
}

const initStrongHold = () =>
  Effect.promise(async () => {
    const vaultPath = `${await appDataDir()}/vault.hold`;

    const vaultPassword = await commands.getVaultPassword();

    const stronghold = await Stronghold.load(vaultPath, vaultPassword);

    try {
      return [
        stronghold,
        await stronghold.loadClient("square_credentials"),
      ] as const;
    } catch {
      return [
        stronghold,
        await stronghold.createClient("square_credentials"),
      ] as const;
    }
  });
const getPassword = (server: RecommendedServerInfo, user: string) =>
  Effect.gen(function* () {
    const [_, client] = yield* initStrongHold();

    const userKey = createKey(server.systemInfo?.Id as string, user);

    const store = client.getStore();

    const data = yield* Effect.tryPromise({
      try: () => store.get(userKey),
      catch: () => new NoPasswordFound(),
    });

    if (!data) {
      return yield* new NoPasswordFound();
    }

    const password = new TextDecoder().decode(new Uint8Array(data));

    return password;
  });

const setPassword = (
  server: RecommendedServerInfo,
  user: string,
  password: string
) =>
  Effect.gen(function* () {
    const [stronghold, client] = yield* initStrongHold();

    const userKey = createKey(server.systemInfo?.Id as string, user);

    const store = client.getStore();
    const encodePassword = Array.from(new TextEncoder().encode(password));

    return yield* Effect.tryPromise({
      try: async () => {
        await store.remove(userKey);
        await store.insert(userKey, encodePassword);

        await stronghold.save();
      },
      catch: (_e) => new AuthError({ message: "Not Able to Save Password" }),
    });
  });

/*
 *
 *
 *
 * Auth Service
 *
 *
 *
 */

export class AuthService extends Effect.Service<AuthService>()("AuthService", {
  dependencies: [AuthStorageServiceLayer, JellyfinClientServiceLayer],
  effect: Effect.gen(function* () {
    const authStorage = yield* AuthStorageService;
    const jfclient = yield* JellyfinClientService;
    const apiRef = yield* Ref.make<Api | null>(null);
    const userRef = yield* Ref.make<UserDto | null>(null);

    /*
     *
     *
     * Methods
     *
     *
     */

    const getUser = () =>
      authStorage.get("user").pipe(
        Effect.mapError(() => new NoUserFound()),
        Effect.flatMap((data) =>
          data === null ? Effect.fail(new NoUserFound()) : Effect.succeed(data)
        ),
        Effect.tap((data) => Ref.set(userRef, data))
      );
    const getAccessToken = () =>
      authStorage.get("accessToken").pipe(
        Effect.mapError(() => new NoTokenFound()),
        Effect.flatMap((data) =>
          data === null ? Effect.fail(new NoTokenFound()) : Effect.succeed(data)
        )
      );

    const getServer = () =>
      authStorage.get("server").pipe(
        Effect.mapError(() => new NoServerFound()),
        Effect.flatMap((data) =>
          data === null
            ? Effect.fail(new NoServerFound())
            : Effect.succeed(data)
        )
      );

    const getApi = () =>
      Effect.gen(function* () {
        // Check if we already have a cached API
        const cachedApi = yield* Ref.get(apiRef);

        if (cachedApi) {
          return cachedApi;
        }

        // Get server info
        const server = yield* authStorage.get("server").pipe(
          Effect.mapError(() => new NoServerFound()),
          Effect.flatMap((data) =>
            data === null
              ? Effect.fail(new NoServerFound())
              : Effect.succeed(data)
          )
        );

        // Get access token
        const token = yield* authStorage.get("accessToken").pipe(
          Effect.mapError(() => new NoTokenFound()),
          Effect.flatMap((data) =>
            data === null
              ? Effect.fail(new NoTokenFound())
              : Effect.succeed(data)
          )
        );

        // Create new API instance
        const api = yield* jfclient.getApi(server, token);

        // Only cache the API if we have a valid token
        if (token) {
          yield* Ref.set(apiRef, api);
        }

        return api;
      });

    const login = (
      server: RecommendedServerInfo,
      username: string,
      password: string
    ) =>
      Effect.gen(function* () {
        const api = yield* jfclient.getApi(server);

        const data = yield* Effect.tryPromise({
          try: () => api.authenticateUserByName(username, password),
          catch: (e) => new AuthError({ message: (e as Error).message }),
        }).pipe(
          Effect.flatMap((data) =>
            data.status !== 200
              ? Effect.fail(new AuthError({ message: data.statusText }))
              : Effect.succeed(data)
          )
        );

        // yield* jfclient.addUser(server, username);

        yield* authStorage.set("accessToken", data.data.AccessToken ?? "");
        yield* authStorage.set("user", data.data.User ?? null);
        yield* authStorage.set("server", server);

        yield* Effect.runFork(getApi());
        yield* Effect.runFork(getUser());
      });

    const logout = () =>
      Effect.gen(function* () {
        // Clear cached API on logout
        yield* Ref.set(apiRef, null);
        yield* Ref.set(userRef, null);

        yield* authStorage.remove("accessToken");
        yield* authStorage.remove("user");
        yield* authStorage.remove("server");
      });

    return {
      getPassword,
      setPassword,
      getUser,
      getAccessToken,
      getServer,
      getApi,
      login,
      logout,
    };
  }),
}) {}

export const AuthServiceLayer = AuthService.Default;

import { Data } from "effect";

