// biome-ignore lint/complexity/noBannedTypes: Tagged Error
export class NoServerFound extends Data.TaggedError("NoServerFound")<{}> {}

// biome-ignore lint/complexity/noBannedTypes: Tagged Error
export class NoUserFound extends Data.TaggedError("NoUserFound")<{}> {}

// biome-ignore lint/complexity/noBannedTypes: Tagged Error
